const WORD_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const DRAWING_NS = 'http://schemas.openxmlformats.org/drawingml/2006/main';

export interface StyleFontInfo {
  font: string | null;
  size: number | null; // points
  color: [number, number, number] | null;
  bold: boolean;
  italic: boolean;
}

const EMPTY: StyleFontInfo = { font: null, size: null, color: null, bold: false, italic: false };

export interface DocStyleDefaults {
  /** Resolves the *inherited* font/size/color for a paragraph style (walking
   * its `w:basedOn` chain up to the document's own defaults) -- this is what
   * a run in that paragraph renders as when it has no direct formatting of
   * its own. Direct run formatting (already read by mammoth, or injected by
   * colorInjection.ts) always takes priority over this. */
  resolveForStyle(styleId: string | null | undefined): StyleFontInfo;
}

interface RawStyleEntry {
  basedOn: string | null;
  font: string | null;
  size: number | null;
  color: [number, number, number] | null;
  bold: boolean | null;
  italic: boolean | null;
}

function themeKeyFor(value: string | null): 'major' | 'minor' | null {
  if (!value) return null;
  const lower = value.toLowerCase();
  if (lower.startsWith('major')) return 'major';
  if (lower.startsWith('minor')) return 'minor';
  return null;
}

function readFont(rPr: Element | undefined, themeFonts: { major: string | null; minor: string | null }): string | null {
  const rFonts = rPr?.getElementsByTagNameNS(WORD_NS, 'rFonts')[0];
  if (!rFonts) return null;
  const ascii = rFonts.getAttributeNS(WORD_NS, 'ascii');
  if (ascii) return ascii;
  const key = themeKeyFor(rFonts.getAttributeNS(WORD_NS, 'asciiTheme'));
  return key ? themeFonts[key] : null;
}

function readSize(rPr: Element | undefined): number | null {
  const val = rPr?.getElementsByTagNameNS(WORD_NS, 'sz')[0]?.getAttributeNS(WORD_NS, 'val') ?? null;
  if (!val || !/^[0-9]+$/.test(val)) return null;
  // w:sz is in half-points.
  return parseInt(val, 10) / 2;
}

function readColor(rPr: Element | undefined): [number, number, number] | null {
  const val = rPr?.getElementsByTagNameNS(WORD_NS, 'color')[0]?.getAttributeNS(WORD_NS, 'val') ?? null;
  if (!val || val.toLowerCase() === 'auto' || !/^[0-9a-fA-F]{6}$/.test(val)) return null;
  return [parseInt(val.slice(0, 2), 16) / 255, parseInt(val.slice(2, 4), 16) / 255, parseInt(val.slice(4, 6), 16) / 255];
}

// Presence, not just value, matters here: `<w:b/>` (no w:val) means true,
// `<w:b w:val="0"/>` means explicitly false (and should still stop the
// basedOn chain rather than be treated as "not specified") -- only a
// missing `<w:b>` element entirely should fall through to the parent style.
function readBoolFlag(rPr: Element | undefined, tag: string): boolean | null {
  const el = rPr?.getElementsByTagNameNS(WORD_NS, tag)[0];
  if (!el) return null;
  const val = el.getAttributeNS(WORD_NS, 'val');
  return val !== 'false' && val !== '0';
}

/** Reads `word/theme/theme1.xml` and `word/styles.xml` so a run's *inherited*
 * font/size/color can be resolved from its paragraph style -- not just the
 * direct per-run formatting mammoth exposes. Most normal Word documents set
 * their body/heading appearance entirely through styles (the "Normal" and
 * "HeadingN" styles, often themselves pointing at the document's theme
 * fonts) rather than direct formatting on every run, so without this a
 * typical document's real font, size, and heading color are invisible to
 * the converter and everything falls back to generic defaults regardless of
 * what the document actually specifies. */
export async function readDocStyleDefaults(file: File): Promise<DocStyleDefaults> {
  try {
    const { default: JSZip } = await import('jszip');
    const zip = await JSZip.loadAsync(file);

    let themeFonts: { major: string | null; minor: string | null } = { major: null, minor: null };
    const themeXml = await zip.file('word/theme/theme1.xml')?.async('string');
    if (themeXml) {
      const themeDoc = new DOMParser().parseFromString(themeXml, 'application/xml');
      if (!themeDoc.querySelector('parsererror')) {
        const readLatin = (tag: string) => {
          const scopeEl = themeDoc.getElementsByTagNameNS(DRAWING_NS, tag)[0];
          const typeface = scopeEl?.getElementsByTagNameNS(DRAWING_NS, 'latin')[0]?.getAttribute('typeface');
          return typeface || null;
        };
        themeFonts = { major: readLatin('majorFont'), minor: readLatin('minorFont') };
      }
    }

    const stylesXml = await zip.file('word/styles.xml')?.async('string');
    if (!stylesXml) return { resolveForStyle: () => EMPTY };
    const stylesDoc = new DOMParser().parseFromString(stylesXml, 'application/xml');
    if (stylesDoc.querySelector('parsererror')) return { resolveForStyle: () => EMPTY };

    const defaultRPr = stylesDoc.getElementsByTagNameNS(WORD_NS, 'rPrDefault')[0]?.getElementsByTagNameNS(WORD_NS, 'rPr')[0];
    const docDefault = {
      font: readFont(defaultRPr, themeFonts),
      size: readSize(defaultRPr),
      color: readColor(defaultRPr),
      bold: readBoolFlag(defaultRPr, 'b') ?? false,
      italic: readBoolFlag(defaultRPr, 'i') ?? false,
    };

    const styles = new Map<string, RawStyleEntry>();
    Array.from(stylesDoc.getElementsByTagNameNS(WORD_NS, 'style')).forEach((styleEl) => {
      const styleId = styleEl.getAttributeNS(WORD_NS, 'styleId');
      if (!styleId) return;
      const rPr = styleEl.getElementsByTagNameNS(WORD_NS, 'rPr')[0];
      const basedOn = styleEl.getElementsByTagNameNS(WORD_NS, 'basedOn')[0]?.getAttributeNS(WORD_NS, 'val') ?? null;
      styles.set(styleId, {
        basedOn,
        font: readFont(rPr, themeFonts),
        size: readSize(rPr),
        color: readColor(rPr),
        bold: readBoolFlag(rPr, 'b'),
        italic: readBoolFlag(rPr, 'i'),
      });
    });

    function resolveForStyle(styleId: string | null | undefined): StyleFontInfo {
      let currentId: string | null = styleId || 'Normal';
      let font: string | null = null;
      let size: number | null = null;
      let color: [number, number, number] | null = null;
      let bold: boolean | null = null;
      let italic: boolean | null = null;
      const seen = new Set<string>();

      while (currentId && !seen.has(currentId)) {
        seen.add(currentId);
        const entry: RawStyleEntry | undefined = styles.get(currentId);
        if (!entry) break;
        if (font === null) font = entry.font;
        if (size === null) size = entry.size;
        if (color === null) color = entry.color;
        if (bold === null) bold = entry.bold;
        if (italic === null) italic = entry.italic;
        if (font !== null && size !== null && color !== null && bold !== null && italic !== null) break;
        currentId = entry.basedOn;
      }

      return {
        font: font ?? docDefault.font,
        size: size ?? docDefault.size,
        color: color ?? docDefault.color,
        bold: bold ?? docDefault.bold,
        italic: italic ?? docDefault.italic,
      };
    }

    return { resolveForStyle };
  } catch {
    return { resolveForStyle: () => EMPTY };
  }
}
