// Word's own fonts (Calibri, Cambria, ...) can't legally be bundled, so
// "match the document" means embedding the closest open-license,
// metric-compatible substitute instead — the same substitution
// LibreOffice/Google Docs make for the same reason. All five are Google's
// (formerly Ascender's) metric-compatible family, OFL-licensed:
//   Carlito ~ Calibri · Caladea ~ Cambria · Arimo ~ Arial/Helvetica
//   Tinos ~ Times New Roman · Cousine ~ Courier New/Consolas
import carlitoRegularUrl from '@fontsource/carlito/files/carlito-latin-400-normal.woff?url';
import carlitoBoldUrl from '@fontsource/carlito/files/carlito-latin-700-normal.woff?url';
import carlitoItalicUrl from '@fontsource/carlito/files/carlito-latin-400-italic.woff?url';
import carlitoBoldItalicUrl from '@fontsource/carlito/files/carlito-latin-700-italic.woff?url';
import caladeaRegularUrl from '@fontsource/caladea/files/caladea-latin-400-normal.woff?url';
import caladeaBoldUrl from '@fontsource/caladea/files/caladea-latin-700-normal.woff?url';
import caladeaItalicUrl from '@fontsource/caladea/files/caladea-latin-400-italic.woff?url';
import caladeaBoldItalicUrl from '@fontsource/caladea/files/caladea-latin-700-italic.woff?url';
import arimoRegularUrl from '@fontsource/arimo/files/arimo-latin-400-normal.woff?url';
import arimoBoldUrl from '@fontsource/arimo/files/arimo-latin-700-normal.woff?url';
import arimoItalicUrl from '@fontsource/arimo/files/arimo-latin-400-italic.woff?url';
import arimoBoldItalicUrl from '@fontsource/arimo/files/arimo-latin-700-italic.woff?url';
import tinosRegularUrl from '@fontsource/tinos/files/tinos-latin-400-normal.woff?url';
import tinosBoldUrl from '@fontsource/tinos/files/tinos-latin-700-normal.woff?url';
import tinosItalicUrl from '@fontsource/tinos/files/tinos-latin-400-italic.woff?url';
import tinosBoldItalicUrl from '@fontsource/tinos/files/tinos-latin-700-italic.woff?url';
import cousineRegularUrl from '@fontsource/cousine/files/cousine-latin-400-normal.woff?url';
import cousineBoldUrl from '@fontsource/cousine/files/cousine-latin-700-normal.woff?url';
import cousineItalicUrl from '@fontsource/cousine/files/cousine-latin-400-italic.woff?url';
import cousineBoldItalicUrl from '@fontsource/cousine/files/cousine-latin-700-italic.woff?url';

import type { PDFDocument, PDFFont } from 'pdf-lib';

export type FontFamilyKey = 'carlito' | 'caladea' | 'arimo' | 'tinos' | 'cousine';

/** Embeds font bytes of unknown provenance (in particular, a visitor's own
 * installed system font via Local Font Access -- fonts.ts's own bundled
 * substitutes are already known-good). Real-world installed font files can
 * be TrueType collections (Windows ships "Cambria" as `cambria.ttc`, a
 * container of multiple font programs rather than a single usable one),
 * variable fonts, or otherwise a shape fontkit can parse but not fully
 * drive -- these don't necessarily fail at embed time, but throw later from
 * deep inside pdf-lib/fontkit's text-shaping code the first time something
 * actually tries to measure or draw with them. A throwaway measurement
 * right after embedding surfaces that immediately, so the caller can fall
 * back to the substitute font instead of the whole conversion crashing
 * partway through. Returns null (never throws) for anything unusable. */
export async function embedFontResilient(pdfDoc: PDFDocument, bytes: Uint8Array): Promise<PDFFont | null> {
  for (const subset of [true, false]) {
    try {
      const font = await pdfDoc.embedFont(bytes, { subset });
      font.widthOfTextAtSize('Test 123', 12); // smoke test -- throws for e.g. TTC collections
      return font;
    } catch {
      // try the next strategy, or give up below
    }
  }
  return null;
}

interface FontVariantUrls {
  regular: string;
  bold: string;
  italic: string;
  boldItalic: string;
}

const FONT_URLS: Record<FontFamilyKey, FontVariantUrls> = {
  carlito: { regular: carlitoRegularUrl, bold: carlitoBoldUrl, italic: carlitoItalicUrl, boldItalic: carlitoBoldItalicUrl },
  caladea: { regular: caladeaRegularUrl, bold: caladeaBoldUrl, italic: caladeaItalicUrl, boldItalic: caladeaBoldItalicUrl },
  arimo: { regular: arimoRegularUrl, bold: arimoBoldUrl, italic: arimoItalicUrl, boldItalic: arimoBoldItalicUrl },
  tinos: { regular: tinosRegularUrl, bold: tinosBoldUrl, italic: tinosItalicUrl, boldItalic: tinosBoldItalicUrl },
  cousine: { regular: cousineRegularUrl, bold: cousineBoldUrl, italic: cousineItalicUrl, boldItalic: cousineBoldItalicUrl },
};

const DEFAULT_FAMILY: FontFamilyKey = 'carlito'; // modern Word's own default is Calibri

/** Maps a font name as declared in the .docx (`w:rFonts`) to the closest
 * embeddable substitute. Falls back to the Calibri substitute — the most
 * common modern-Word default — for anything unrecognized or unset. */
export function detectFontFamily(rawName: string | null | undefined): FontFamilyKey {
  const name = (rawName ?? '').toLowerCase();
  if (name === '') return DEFAULT_FAMILY;
  if (/calibri/.test(name)) return 'carlito';
  if (/cambria/.test(name)) return 'caladea';
  if (/times|georgia|garamond|book antiqua|palatino|cambria math/.test(name)) return 'tinos';
  if (/courier|consolas|menlo|monaco|monospace|lucida console/.test(name)) return 'cousine';
  if (/arial|helvetica|verdana|tahoma|segoe|trebuchet|calibri light/.test(name)) return 'arimo';
  return DEFAULT_FAMILY;
}

export interface FontVariantBytes {
  regular: Uint8Array;
  bold: Uint8Array;
  italic: Uint8Array;
  boldItalic: Uint8Array;
}

const byteCache = new Map<string, Promise<Uint8Array>>();

function fetchBytes(url: string): Promise<Uint8Array> {
  let cached = byteCache.get(url);
  if (!cached) {
    cached = fetch(url)
      .then((res) => res.arrayBuffer())
      .then((buf) => new Uint8Array(buf));
    byteCache.set(url, cached);
  }
  return cached;
}

const familyCache = new Map<FontFamilyKey, Promise<FontVariantBytes>>();

/** Fetches (and caches) the four variant files for one font family. The same
 * bytes get embedded into two separate PDFDocuments per conversion — one
 * throwaway document used just for measurement, one for the real output —
 * since pdf-lib fonts can't be reused across documents, but raw bytes can. */
export function loadFontFamilyBytes(family: FontFamilyKey): Promise<FontVariantBytes> {
  let cached = familyCache.get(family);
  if (!cached) {
    const urls = FONT_URLS[family];
    cached = Promise.all([fetchBytes(urls.regular), fetchBytes(urls.bold), fetchBytes(urls.italic), fetchBytes(urls.boldItalic)]).then(
      ([regular, bold, italic, boldItalic]) => ({ regular, bold, italic, boldItalic }),
    );
    familyCache.set(family, cached);
  }
  return cached;
}
