import { injectColorMarkers, splitColorMarker } from './colorInjection';
import { HIGHLIGHT_COLOR_RGB } from './highlightColors';
import { readDocStyleDefaults, type DocStyleDefaults, type StyleFontInfo } from './styleDefaults';
import type { DocxBlock, DocxRun, ParagraphAlign } from './types';

export interface ParseDocxResult {
  blocks: DocxBlock[];
  warnings: string[];
}

// Mammoth's internal document model (built from the raw OOXML, before HTML
// conversion) carries far more than its HTML output ever exposes — no style
// map or transform can make mammoth's HTML include a run's font, size, or
// alignment info, because document-to-html.js's converter simply never
// looks at those properties when deciding what to emit. `transformDocument`
// is mammoth's public, documented hook for this exact model — the shapes
// below mirror it (see mammoth/lib/documents.js), but only that hook is
// used, never mammoth's internal module paths directly.
interface MNode {
  type: string;
}
interface MText extends MNode {
  type: 'text';
  value: string;
}
interface MTab extends MNode {
  type: 'tab';
}
interface MBreak extends MNode {
  type: 'break';
  breakType: 'line' | 'page' | 'column';
}
interface MRun extends MNode {
  type: 'run';
  children: MNode[];
  isBold: boolean;
  isItalic: boolean;
  isUnderline: boolean;
  isStrikethrough: boolean;
  verticalAlignment: 'baseline' | 'superscript' | 'subscript';
  font: string | null;
  fontSize: number | null;
  highlight: string | null;
}
interface MHyperlink extends MNode {
  type: 'hyperlink';
  children: MNode[];
  href?: string;
}
interface MImage extends MNode {
  type: 'image';
  contentType: string;
  readAsBase64String(): Promise<string>;
}
interface MParagraph extends MNode {
  type: 'paragraph';
  children: MNode[];
  styleId: string | null;
  styleName: string | null;
  alignment: string | null;
  numbering: { isOrdered: boolean; level: string } | null;
}
interface MTableCell extends MNode {
  type: 'tableCell';
  children: MNode[];
}
interface MTableRow extends MNode {
  type: 'tableRow';
  children: MTableCell[];
  isHeader: boolean;
}
interface MTable extends MNode {
  type: 'table';
  children: MTableRow[];
}
interface MDocument extends MNode {
  type: 'document';
  children: MNode[];
}

function hasChildren(node: MNode): node is MNode & { children: MNode[] } {
  return Array.isArray((node as { children?: unknown }).children);
}

function headingLevelOf(paragraph: MParagraph): 1 | 2 | 3 | 4 | 5 | 6 | null {
  const styleId = (paragraph.styleId ?? '').toLowerCase();
  const styleName = (paragraph.styleName ?? '').toLowerCase();
  const clamp = (n: number) => Math.min(6, Math.max(1, n)) as 1 | 2 | 3 | 4 | 5 | 6;

  const idMatch = /^heading(\d)$/.exec(styleId);
  if (idMatch) return clamp(Number(idMatch[1]));
  const nameMatch = /^heading (\d)$/.exec(styleName);
  if (nameMatch) return clamp(Number(nameMatch[1]));
  // Apple Pages' generic "Heading" style, with no level suffix.
  if (styleId === 'heading' || styleName === 'heading') return 1;
  return null;
}

function normalizeAlign(raw: string | null): ParagraphAlign | undefined {
  if (raw === 'center') return 'center';
  if (raw === 'right') return 'right';
  if (raw === 'both') return 'justify';
  return undefined;
}

// A run's children are Text/Tab/(line)Break leaves — collects them into one
// string. Images are handled separately (see findImages) rather than as text.
function collectRunText(children: MNode[]): string {
  let text = '';
  for (const child of children) {
    if (child.type === 'text') text += (child as MText).value;
    else if (child.type === 'tab') text += '\t';
    else if (child.type === 'break' && (child as MBreak).breakType === 'line') text += '\n';
  }
  return text;
}

function findImages(node: MNode, out: MImage[]): void {
  if (node.type === 'image') {
    out.push(node as MImage);
    return;
  }
  if (hasChildren(node)) node.children.forEach((child) => findImages(child, out));
}

async function imageToDataUrl(image: MImage): Promise<string | null> {
  try {
    const base64 = await image.readAsBase64String();
    return `data:${image.contentType};base64,${base64}`;
  } catch {
    return null;
  }
}

// Walks a paragraph's (or table cell's) content, flattening Run and
// Hyperlink-wrapped-Run nodes into a run list — mirroring the inline
// formatting a reader would see, in document order. `fallback` is the
// paragraph's *inherited* font/size/color (resolved from its style, see
// styleDefaults.ts) — used only when a run has no direct formatting of its
// own, which is the common case: most normal documents set their body and
// heading appearance through styles, not per-run overrides.
function extractRuns(nodes: MNode[], href: string | undefined, fallback: StyleFontInfo, out: DocxRun[]): void {
  for (const node of nodes) {
    if (node.type === 'run') {
      const run = node as MRun;
      const text = collectRunText(run.children);
      if (text === '') continue;

      const { font, color } = splitColorMarker(run.font);
      out.push({
        text,
        // A run's own w:b/w:i always mean it was set directly, so it wins
        // outright; only fall back to the paragraph style's resolved
        // bold/italic when the run says nothing about it at all -- which
        // mammoth can't distinguish from an explicit "off", but that's a
        // mammoth API limitation, not something worth reaching around it for.
        bold: run.isBold || fallback.bold,
        italic: run.isItalic || fallback.italic,
        underline: run.isUnderline,
        strikethrough: run.isStrikethrough,
        superscript: run.verticalAlignment === 'superscript',
        subscript: run.verticalAlignment === 'subscript',
        highlightColor: run.highlight ? HIGHLIGHT_COLOR_RGB[run.highlight] : undefined,
        color: color ?? fallback.color,
        font: font ?? fallback.font,
        fontSize: run.fontSize ?? fallback.size,
        href,
      });
    } else if (node.type === 'hyperlink') {
      const link = node as MHyperlink;
      extractRuns(link.children, link.href ?? href, fallback, out);
    }
    // Any other sibling type at this level (bookmarks, note references, ...) is ignored.
  }
}

function isBlank(runs: DocxRun[]): boolean {
  return runs.every((r) => r.text.trim() === '');
}

interface WalkContext {
  onSkippedImages: (count: number) => void;
  styleDefaults: DocStyleDefaults;
}

async function walkParagraph(paragraph: MParagraph, blocks: DocxBlock[], ctx: WalkContext): Promise<void> {
  const runs: DocxRun[] = [];
  extractRuns(paragraph.children, undefined, ctx.styleDefaults.resolveForStyle(paragraph.styleId), runs);

  const images: MImage[] = [];
  paragraph.children.forEach((child) => findImages(child, images));

  if (images.length === 1 && isBlank(runs)) {
    const dataUrl = await imageToDataUrl(images[0]);
    if (dataUrl) blocks.push({ kind: 'image', dataUrl });
    else ctx.onSkippedImages(1);
    return;
  }
  if (images.length > 0) ctx.onSkippedImages(images.length);
  if (isBlank(runs)) return;

  const align = normalizeAlign(paragraph.alignment);
  const headingLevel = headingLevelOf(paragraph);

  if (headingLevel) {
    blocks.push({ kind: 'heading', level: headingLevel, runs, align });
  } else if (paragraph.numbering) {
    blocks.push({ kind: 'list-item', ordered: paragraph.numbering.isOrdered, level: Number(paragraph.numbering.level) || 0, runs, align });
  } else {
    blocks.push({ kind: 'paragraph', runs, align });
  }
}

async function walkTable(table: MTable, blocks: DocxBlock[], ctx: WalkContext): Promise<void> {
  const rows: DocxRun[][][] = [];

  for (const row of table.children) {
    const cells: DocxRun[][] = [];
    for (const cell of row.children) {
      // A cell's own children are paragraphs (occasionally more than one) —
      // flattened into a single run list per cell, same simplification as
      // for merged/spanned cells (see the tool's caveats).
      const cellRuns: DocxRun[] = [];
      for (const cellChild of cell.children) {
        if (cellChild.type === 'paragraph') {
          const paragraph = cellChild as MParagraph;
          extractRuns(paragraph.children, undefined, ctx.styleDefaults.resolveForStyle(paragraph.styleId), cellRuns);
        }
      }
      cells.push(row.isHeader ? cellRuns.map((r) => ({ ...r, bold: true })) : cellRuns);
    }
    if (cells.length > 0) rows.push(cells);
  }

  if (rows.length > 0) blocks.push({ kind: 'table', rows });
}

/** Converts a .docx File into a flat block list, read directly from
 * mammoth's internal document model (see the M* interfaces above) rather
 * than its HTML output — the only way to get at a run's actual font, size,
 * and color, none of which mammoth's HTML conversion exposes. */
export async function parseDocx(file: File): Promise<ParseDocxResult> {
  // mammoth is a sizeable dependency (its own docx-parsing/style engine) that's
  // only ever needed once a visitor actually converts a file, not just for
  // loading the tool's upload UI -- deferred the same way pdf-lib/pdfjs/jszip
  // already are elsewhere in this codebase (see src/lib/pdf/*.ts).
  const [{ default: mammoth }, arrayBuffer, styleDefaults] = await Promise.all([
    import('mammoth'),
    injectColorMarkers(file),
    readDocStyleDefaults(file),
  ]);

  let captured: MDocument | null = null;
  const { messages } = await mammoth.convertToHtml(
    { arrayBuffer },
    {
      transformDocument: (doc: MDocument) => {
        captured = doc;
        return doc;
      },
    },
  );
  const warnings = messages.filter((m) => m.type === 'warning' || m.type === 'error').map((m) => m.message);

  if (!captured) {
    throw new Error("Couldn't read this document's structure.");
  }

  const blocks: DocxBlock[] = [];
  let skippedInlineImages = 0;
  const ctx: WalkContext = {
    onSkippedImages: (count) => {
      skippedInlineImages += count;
    },
    styleDefaults,
  };

  for (const child of (captured as MDocument).children) {
    if (child.type === 'paragraph') await walkParagraph(child as MParagraph, blocks, ctx);
    else if (child.type === 'table') await walkTable(child as MTable, blocks, ctx);
  }

  if (skippedInlineImages > 0) {
    warnings.push(
      `${skippedInlineImages} image${skippedInlineImages === 1 ? '' : 's'} placed inline within a line of text couldn't be positioned and ${skippedInlineImages === 1 ? 'was' : 'were'} skipped.`,
    );
  }

  return { blocks, warnings };
}
