// The Local Font Access API (Chrome/Edge desktop only, behind a one-time
// permission prompt) lets a page read font files already installed on the
// visitor's own machine -- not redistribute them, just borrow the copy the
// visitor (or their copy of Windows/Office) already has a license for. This
// is the only legitimate way to get the *actual* Calibri/Cambria/Times New
// Roman into the output PDF; everywhere else (Firefox, Safari, mobile, or a
// visitor who declines/lacks the font) falls back to the metric-compatible
// open-license substitutes in fonts.ts. TypeScript's DOM lib doesn't know
// about this API yet, hence the ambient declarations below.
interface FontData {
  readonly family: string;
  readonly fullName: string;
  readonly postscriptName: string;
  readonly style: string;
  blob(): Promise<Blob>;
}

declare global {
  interface Window {
    queryLocalFonts?: () => Promise<FontData[]>;
  }
}

export function isLocalFontAccessSupported(): boolean {
  return typeof window !== 'undefined' && typeof window.queryLocalFonts === 'function';
}

let fontListPromise: Promise<FontData[]> | null = null;

// `queryLocalFonts()` itself triggers the permission prompt on first call
// (and throws if the visitor declines) -- calling it once up front, when the
// user opts in via the checkbox, gives immediate, actionable feedback
// instead of silently falling back to substitutes partway through a convert.
export async function requestLocalFontsAccess(): Promise<boolean> {
  if (!isLocalFontAccessSupported()) return false;
  try {
    fontListPromise = window.queryLocalFonts!();
    await fontListPromise;
    return true;
  } catch {
    fontListPromise = null;
    return false;
  }
}

function styleMatches(style: string, bold: boolean, italic: boolean): boolean {
  const s = style.toLowerCase();
  const hasBold = /bold/.test(s);
  const hasItalic = /italic|oblique/.test(s);
  return hasBold === bold && hasItalic === italic;
}

const bytesCache = new Map<string, Promise<Uint8Array | null>>();

/** Finds and fetches the closest installed local font face matching a
 * document's declared font name and bold/italic combination. Returns null
 * (never throws) when local font access wasn't granted, the family isn't
 * installed, or no variant with a matching weight/style exists -- the
 * caller should embed the usual substitute font in that case. */
export function loadLocalFontVariantBytes(rawName: string | null | undefined, bold: boolean, italic: boolean): Promise<Uint8Array | null> {
  const family = (rawName ?? '').trim();
  const key = `${family.toLowerCase()}|${bold}|${italic}`;
  let cached = bytesCache.get(key);
  if (cached) return cached;

  cached = (async () => {
    if (!family || !fontListPromise) return null;
    const fonts = await fontListPromise;
    const candidates = fonts.filter((f) => f.family.toLowerCase() === family.toLowerCase());
    if (candidates.length === 0) return null;

    const exact = candidates.find((f) => styleMatches(f.style, bold, italic));
    // Word documents commonly mark bold/italic on a run using the *base*
    // family name (e.g. "Calibri" for a bold run, not "Calibri Bold") --
    // still worth using an available face closest to what was asked for
    // rather than giving up and falling back to the substitute entirely.
    const fallback = candidates.find((f) => styleMatches(f.style, false, false)) ?? candidates[0];
    const chosen = exact ?? fallback;

    try {
      const blob = await chosen.blob();
      return new Uint8Array(await blob.arrayBuffer());
    } catch {
      return null;
    }
  })();

  bytesCache.set(key, cached);
  return cached;
}
