// Word (and its AutoCorrect) routinely inserts Unicode punctuation that
// looks identical to a plain ASCII character but isn't one -- a real HYPHEN
// (U+2010) instead of hyphen-minus, a SOFT HYPHEN at a wrap point, a
// zero-width space, etc. None of these are in even a comprehensive font's
// "latin" glyph subset (verified against Carlito directly), so left alone
// they'd fall back to a "?" even though the visible fix is trivial: treat
// them as the character they're standing in for. Applied before glyph-
// coverage checking, not as a substitute for it -- genuinely unsupported
// scripts still fall back to "?".
//
// Each pattern is built from a numeric code point with String.fromCharCode
// rather than a literal character or a \u escape in source, so there's no
// invisible/lookalike character sitting in this file that could itself be
// miscopied.
function charsFrom(codePoints: number[]): string {
  return codePoints.map((cp) => String.fromCharCode(cp)).join('');
}

// hyphen (2010), non-breaking hyphen (2011), figure dash (2012), minus sign (2212)
const HYPHEN_LIKE = new RegExp('[' + charsFrom([0x2010, 0x2011, 0x2012, 0x2212]) + ']', 'g');
// horizontal bar (2015) -> em dash
const HORIZONTAL_BAR = new RegExp(charsFrom([0x2015]), 'g');
// soft hyphen (00AD), BOM/zero-width-no-break-space (FEFF), zero-width space (200B),
// zero-width non-joiner (200C), zero-width joiner (200D) -- all invisible either way
const INVISIBLE = new RegExp('[' + charsFrom([0x00ad, 0xfeff, 0x200b, 0x200c, 0x200d]) + ']', 'g');

export function normalizeText(text: string): string {
  return text.replace(HYPHEN_LIKE, '-').replace(HORIZONTAL_BAR, charsFrom([0x2014])).replace(INVISIBLE, '');
}
