import type { PageGeometry } from './types';

const WORD_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const TWIPS_PER_POINT = 20;

function twipsToPoints(value: string | null): number | null {
  if (value === null) return null;
  const n = Number(value);
  return Number.isFinite(n) ? n / TWIPS_PER_POINT : null;
}

/** Reads the page size and margins straight from the document's own
 * `word/document.xml` (`w:pgSz` / `w:pgMar`) — backs the "Match the document"
 * page-size/margins options. Returns null if the file can't be read as a
 * .docx zip, or the first section has no explicit page size (documents with
 * more than one section/page-size are simplified to just the first one's). */
export async function readDocxPageGeometry(file: File): Promise<PageGeometry | null> {
  try {
    const { default: JSZip } = await import('jszip');
    const zip = await JSZip.loadAsync(file);
    const xml = await zip.file('word/document.xml')?.async('string');
    if (!xml) return null;

    const parsed = new DOMParser().parseFromString(xml, 'application/xml');
    if (parsed.querySelector('parsererror')) return null;

    const pgSz = parsed.getElementsByTagNameNS(WORD_NS, 'pgSz')[0];
    if (!pgSz) return null;

    const width = twipsToPoints(pgSz.getAttributeNS(WORD_NS, 'w'));
    const height = twipsToPoints(pgSz.getAttributeNS(WORD_NS, 'h'));
    if (!width || !height) return null;

    const pgMar = parsed.getElementsByTagNameNS(WORD_NS, 'pgMar')[0] as Element | undefined;
    const margin = (side: string, fallback: number) => {
      const raw = pgMar?.getAttributeNS(WORD_NS, side) ?? null;
      return twipsToPoints(raw) ?? fallback;
    };

    return {
      width,
      height,
      marginTop: margin('top', 72),
      marginRight: margin('right', 72),
      marginBottom: margin('bottom', 72),
      marginLeft: margin('left', 72),
    };
  } catch {
    return null;
  }
}
