import { parseDocx } from './parse';
import { readDocxPageGeometry } from './pageSetup';
import { readDocxHeaderFooter } from './headerFooter';
import { layoutDocument, resolvePageGeometry } from './layout';
import { renderPdf } from './render';
import type { ConvertResult, WordToPdfOptions } from './types';

const DOCX_MIME = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';

export function looksLikeDocx(file: File): boolean {
  return file.type === DOCX_MIME || file.name.toLowerCase().endsWith('.docx');
}

/** Converts a .docx File into a PDF Blob with real, selectable text — parsed
 * with mammoth, laid out and drawn with pdf-lib, entirely in the browser. */
export async function convertDocxToPdf(file: File, options: WordToPdfOptions): Promise<ConvertResult> {
  const [{ blocks, warnings: parseWarnings }, docGeometry, headerFooter] = await Promise.all([
    parseDocx(file),
    readDocxPageGeometry(file),
    options.includeHeadersFooters ? readDocxHeaderFooter(file) : Promise.resolve({ header: null, footer: null }),
  ]);

  if (blocks.length === 0) {
    throw new Error("Couldn't find any content to convert — this document may be empty or unreadable.");
  }

  const geometry = await resolvePageGeometry(options, docGeometry);

  try {
    const { pages, warnings: layoutWarnings } = await layoutDocument(blocks, geometry, options);
    const blob = await renderPdf(pages, geometry, options, headerFooter);
    return { blob, pageCount: pages.length, warnings: [...parseWarnings, ...layoutWarnings] };
  } catch (err) {
    // Local Font Access hands the converter real, arbitrary files from the
    // visitor's own system -- TrueType collections, variable fonts, and
    // other real-world quirks can make fontkit fail deep inside pdf-lib's
    // glyph/subsetting internals in ways no upfront check can fully rule
    // out. Rather than let one uncooperative installed font fail the whole
    // conversion, redo it with the always-reliable bundled substitutes.
    if (!options.useLocalFonts) throw err;
    const fallbackOptions: WordToPdfOptions = { ...options, useLocalFonts: false };
    const { pages, warnings: layoutWarnings } = await layoutDocument(blocks, geometry, fallbackOptions);
    const blob = await renderPdf(pages, geometry, fallbackOptions, headerFooter);
    return {
      blob,
      pageCount: pages.length,
      warnings: [
        ...parseWarnings,
        ...layoutWarnings,
        "One of your installed fonts couldn't be used in the PDF, so the built-in substitute fonts were used instead.",
      ],
    };
  }
}
