import type JSZip from 'jszip';
import type { HeaderFooterText } from './types';

const WORD_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
const REL_NS = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships';

// Pulls out only the literal, static text of a header/footer part — dynamic
// fields (PAGE, NUMPAGES, DATE, ...) are skipped rather than reproduced,
// since what's stored for them is just whatever value Word last calculated
// and cached, not something that stays correct per page. <w:fldSimple>
// wraps that same kind of cached value inline, so it's skipped wholesale;
// the "complex field" form (fldChar begin/instrText/separate/.../end) is
// tracked by depth so both the instruction and the cached result inside it
// are skipped too.
function extractStaticText(xml: string): string {
  const parsed = new DOMParser().parseFromString(xml, 'application/xml');
  if (parsed.querySelector('parsererror')) return '';

  let text = '';
  let fieldDepth = 0;

  function walk(node: Node): void {
    if (node.nodeType !== Node.ELEMENT_NODE) return;
    const el = node as Element;
    const local = el.localName;

    if (local === 'fldSimple') return;
    if (local === 'fldChar') {
      const type = el.getAttributeNS(WORD_NS, 'fldCharType');
      if (type === 'begin') fieldDepth++;
      else if (type === 'end') fieldDepth = Math.max(0, fieldDepth - 1);
      return;
    }
    if (local === 'instrText') return;
    if (local === 'tab') {
      text += '\t';
      return;
    }
    if (local === 'br') {
      text += '\n';
      return;
    }
    if (local === 't') {
      if (fieldDepth === 0) text += el.textContent ?? '';
      return;
    }

    Array.from(el.childNodes).forEach(walk);
    if (local === 'p' && !text.endsWith('\n')) text += '\n';
  }

  Array.from(parsed.documentElement.childNodes).forEach(walk);
  return text.trim();
}

async function resolvePart(zip: JSZip, refTag: 'headerReference' | 'footerReference'): Promise<string | null> {
  const [relsXml, docXml] = await Promise.all([
    zip.file('word/_rels/document.xml.rels')?.async('string'),
    zip.file('word/document.xml')?.async('string'),
  ]);
  if (!relsXml || !docXml) return null;

  const relsDoc = new DOMParser().parseFromString(relsXml, 'application/xml');
  const docDoc = new DOMParser().parseFromString(docXml, 'application/xml');

  const refs = Array.from(docDoc.getElementsByTagNameNS(WORD_NS, refTag));
  // Prefer the "default" variant (as opposed to "first page"/"even page") —
  // simplification, same spirit as reading only the first section's page setup.
  const ref = refs.find((r) => r.getAttributeNS(WORD_NS, 'type') === 'default') ?? refs[0];
  const rId = ref?.getAttributeNS(REL_NS, 'id');
  if (!rId) return null;

  const relationship = Array.from(relsDoc.getElementsByTagName('Relationship')).find((r) => r.getAttribute('Id') === rId);
  const target = relationship?.getAttribute('Target');
  if (!target) return null;

  const partPath = `word/${target.replace(/^\.?\/+/, '')}`;
  const partXml = await zip.file(partPath)?.async('string');
  return partXml ? extractStaticText(partXml) || null : null;
}

/** Reads the document's default header/footer — static text only, see
 * extractStaticText. Returns nulls (never throws) if the file can't be read
 * as a .docx zip or has no headers/footers. */
export async function readDocxHeaderFooter(file: File): Promise<HeaderFooterText> {
  try {
    const { default: JSZipCtor } = await import('jszip');
    const zip = await JSZipCtor.loadAsync(file);
    const [header, footer] = await Promise.all([resolvePart(zip, 'headerReference'), resolvePart(zip, 'footerReference')]);
    return { header, footer };
  } catch {
    return { header: null, footer: null };
  }
}
