import type { PDFDocument, PDFFont, PDFImage, PDFPage } from 'pdf-lib';
import { embedFontResilient, loadFontFamilyBytes, type FontFamilyKey } from './fonts';
import { loadLocalFontVariantBytes } from './localFonts';
import type { HeaderFooterText, PageGeometry, PositionedItem, WordToPdfOptions } from './types';

const TEXT_RGB: [number, number, number] = [0.08, 0.08, 0.08];
const LINK_RGB: [number, number, number] = [0.15, 0.35, 0.85];
const BORDER_RGB: [number, number, number] = [0.75, 0.75, 0.75];
const MUTED_RGB: [number, number, number] = [0.5, 0.5, 0.5];

/** Replays a computed layout (see layout.ts) into a real PDFDocument — kept
 * separate from layout so fonts are only ever measured/drawn within the
 * document that actually embeds them. */
export async function renderPdf(
  pages: PositionedItem[][],
  geometry: PageGeometry,
  options: WordToPdfOptions,
  headerFooter: HeaderFooterText,
): Promise<Blob> {
  const [{ PDFDocument, PDFName, PDFString, rgb }, { default: fontkit }] = await Promise.all([
    import('pdf-lib'),
    import('@pdf-lib/fontkit'),
  ]);
  const TEXT_COLOR = rgb(...TEXT_RGB);
  const LINK_COLOR = rgb(...LINK_RGB);
  const BORDER_COLOR = rgb(...BORDER_RGB);
  const MUTED_COLOR = rgb(...MUTED_RGB);

  // pdf-lib has no high-level "add a clickable link" helper — this is the
  // documented low-level recipe: build a Link annotation dict and attach it
  // to the page's /Annots array.
  function addLinkAnnotation(page: PDFPage, rect: [number, number, number, number], url: string): void {
    const context = page.doc.context;
    const annotation = context.obj({
      Type: 'Annot',
      Subtype: 'Link',
      Rect: rect,
      Border: [0, 0, 0],
      A: { Type: 'Action', S: 'URI', URI: PDFString.of(url) },
    });
    const ref = context.register(annotation);
    const existing = page.node.Annots();
    if (existing) existing.push(ref);
    else page.node.set(PDFName.of('Annots'), context.obj([ref]));
  }

  const pdfDoc = await PDFDocument.create();
  pdfDoc.registerFontkit(fontkit);

  const fontCache = new Map<string, PDFFont>();
  const getFont = async (rawFont: string | null | undefined, family: FontFamilyKey, bold: boolean, italic: boolean): Promise<PDFFont> => {
    const key = options.useLocalFonts ? `local:${(rawFont ?? '').toLowerCase()}|${bold}|${italic}` : `${family}|${bold}|${italic}`;
    let font = fontCache.get(key);
    if (!font) {
      if (options.useLocalFonts) {
        const localBytes = await loadLocalFontVariantBytes(rawFont, bold, italic);
        if (localBytes) font = (await embedFontResilient(pdfDoc, localBytes)) ?? undefined;
      }
      if (!font) {
        const variants = await loadFontFamilyBytes(family);
        const bytes = bold && italic ? variants.boldItalic : bold ? variants.bold : italic ? variants.italic : variants.regular;
        font = await pdfDoc.embedFont(bytes, { subset: true });
      }
      fontCache.set(key, font);
    }
    return font;
  };
  const marginFont = await getFont(null, 'carlito', false, false);

  const imageCache = new Map<string, PDFImage>();
  const getImage = async (dataUrl: string, format: 'png' | 'jpeg'): Promise<PDFImage> => {
    let image = imageCache.get(dataUrl);
    if (!image) {
      image = format === 'jpeg' ? await pdfDoc.embedJpg(dataUrl) : await pdfDoc.embedPng(dataUrl);
      imageCache.set(dataUrl, image);
    }
    return image;
  };

  const headerText = options.includeHeadersFooters ? headerFooter.header : null;
  const footerText = options.includeHeadersFooters ? headerFooter.footer : null;

  for (let i = 0; i < pages.length; i++) {
    const page = pdfDoc.addPage([geometry.width, geometry.height]);

    for (const item of pages[i]) {
      if (item.type === 'text') {
        const font = await getFont(item.rawFont, item.fontFamily, item.bold, item.italic);
        const color = item.href ? LINK_COLOR : item.color ? rgb(...item.color) : TEXT_COLOR;
        page.drawText(item.text, { x: item.x, y: item.y, size: item.size, font, color });
        if (item.href) {
          const width = font.widthOfTextAtSize(item.text, item.size);
          addLinkAnnotation(page, [item.x, item.y - 2, item.x + width, item.y + item.size], item.href);
        }
      } else if (item.type === 'rect') {
        if (item.fill) {
          page.drawRectangle({ x: item.x, y: item.y, width: item.width, height: item.height, color: rgb(...item.fill) });
        } else {
          page.drawRectangle({ x: item.x, y: item.y, width: item.width, height: item.height, borderColor: BORDER_COLOR, borderWidth: 0.75 });
        }
      } else if (item.type === 'line') {
        const color = item.color ? rgb(...item.color) : LINK_COLOR;
        page.drawLine({ start: { x: item.x1, y: item.y1 }, end: { x: item.x2, y: item.y2 }, thickness: 0.75, color });
      } else if (item.type === 'image') {
        const image = await getImage(item.dataUrl, item.format);
        page.drawImage(image, { x: item.x, y: item.y, width: item.width, height: item.height });
      }
    }

    if (headerText) {
      const size = 9;
      const width = marginFont.widthOfTextAtSize(headerText, size);
      page.drawText(headerText, {
        x: geometry.width / 2 - width / 2,
        y: geometry.height - geometry.marginTop * 0.6,
        size,
        font: marginFont,
        color: MUTED_COLOR,
      });
    }

    // A document footer and page numbers share the same margin band — merge
    // them onto one line rather than risk overlapping text when both are on.
    const footerLabel = options.includePageNumbers ? `Page ${i + 1} of ${pages.length}` : null;
    const combinedFooter = [footerText, footerLabel].filter(Boolean).join('   —   ');
    if (combinedFooter) {
      const size = 9;
      const width = marginFont.widthOfTextAtSize(combinedFooter, size);
      page.drawText(combinedFooter, {
        x: geometry.width / 2 - width / 2,
        y: geometry.marginBottom / 2,
        size,
        font: marginFont,
        color: MUTED_COLOR,
      });
    }
  }

  const bytes = await pdfDoc.save();
  return new Blob([bytes], { type: 'application/pdf' });
}
