function loadImage(dataUrl: string): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('Failed to decode image'));
    img.src = dataUrl;
  });
}

export interface NormalizedImage {
  dataUrl: string;
  format: 'png' | 'jpeg';
  width: number;
  height: number;
}

/** pdf-lib can only embed PNG or JPEG. Word documents can carry other raster
 * formats (GIF, BMP, WebP) or, occasionally, legacy vector formats (WMF/EMF)
 * that browsers can't decode at all — those come back as null so the caller
 * can skip them with a warning instead of failing the whole conversion. */
export async function normalizeImage(dataUrl: string): Promise<NormalizedImage | null> {
  const directMatch = /^data:image\/(png|jpe?g);base64,/i.exec(dataUrl);

  try {
    const img = await loadImage(dataUrl);
    const { naturalWidth: width, naturalHeight: height } = img;
    if (!width || !height) return null;

    if (directMatch) {
      return { dataUrl, format: directMatch[1].toLowerCase().startsWith('jpe') ? 'jpeg' : 'png', width, height };
    }

    // Unsupported format but the browser could still decode it — re-encode
    // as PNG via canvas so pdf-lib can embed it.
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return null;
    ctx.drawImage(img, 0, 0);
    return { dataUrl: canvas.toDataURL('image/png'), format: 'png', width, height };
  } catch {
    return null;
  }
}
