const WORD_NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main';
// A control character no real font name would ever contain, so it's safe to
// use as a delimiter and to search for later without any risk of colliding
// with genuine text.
const COLOR_MARKER = 'COLOR:';

// Mammoth's document model captures a run's font name (`w:rFonts`) but has
// no concept of run color (`w:color`) at all — there's nothing to read once
// mammoth has parsed the file. Rather than trying to correlate a separate
// raw-XML pass against mammoth's model after the fact (risky: any place the
// two traversals don't line up exactly would silently paint the wrong
// word), this rewrites the color onto the *same* attribute mammoth already
// reads for that exact run, before mammoth ever sees the file. The color
// then travels with the run through mammoth's own parsing, guaranteed
// correct, and gets split back out in parse.ts.
export async function injectColorMarkers(file: File): Promise<ArrayBuffer> {
  try {
    const { default: JSZip } = await import('jszip');
    const zip = await JSZip.loadAsync(file);
    const xml = await zip.file('word/document.xml')?.async('string');
    if (!xml) return file.arrayBuffer();

    const doc = new DOMParser().parseFromString(xml, 'application/xml');
    if (doc.querySelector('parsererror')) return file.arrayBuffer();

    let modified = false;
    Array.from(doc.getElementsByTagNameNS(WORD_NS, 'r')).forEach((run) => {
      const rPr = run.getElementsByTagNameNS(WORD_NS, 'rPr')[0];
      if (!rPr) return;
      const colorVal = rPr.getElementsByTagNameNS(WORD_NS, 'color')[0]?.getAttributeNS(WORD_NS, 'val');
      if (!colorVal || colorVal.toLowerCase() === 'auto' || !/^[0-9a-fA-F]{6}$/.test(colorVal)) return;

      let rFonts = rPr.getElementsByTagNameNS(WORD_NS, 'rFonts')[0];
      if (!rFonts) {
        rFonts = doc.createElementNS(WORD_NS, 'w:rFonts');
        rPr.insertBefore(rFonts, rPr.firstChild);
      }
      const existingAscii = rFonts.getAttributeNS(WORD_NS, 'ascii') ?? '';
      if (existingAscii.includes(COLOR_MARKER)) return; // already marked (shouldn't happen, just in case)
      rFonts.setAttributeNS(WORD_NS, 'w:ascii', `${existingAscii}${COLOR_MARKER}${colorVal}`);
      modified = true;
    });

    if (!modified) return file.arrayBuffer();

    const serialized = new XMLSerializer().serializeToString(doc);
    zip.file('word/document.xml', serialized);
    return await zip.generateAsync({ type: 'arraybuffer' });
  } catch {
    // If anything about this preprocessing step fails, fall back to
    // converting the original file — losing run colors is far better than
    // failing the whole conversion over them.
    return file.arrayBuffer();
  }
}

/** Splits a (possibly marker-augmented) `w:rFonts` ascii value back into the
 * real font name and the color it was carrying, if any. */
export function splitColorMarker(rawFont: string | null | undefined): { font: string | null; color: [number, number, number] | null } {
  if (!rawFont) return { font: null, color: null };
  const idx = rawFont.indexOf(COLOR_MARKER);
  if (idx === -1) return { font: rawFont, color: null };

  const font = rawFont.slice(0, idx) || null;
  const hex = rawFont.slice(idx + COLOR_MARKER.length);
  if (!/^[0-9a-fA-F]{6}$/.test(hex)) return { font, color: null };

  return {
    font,
    color: [parseInt(hex.slice(0, 2), 16) / 255, parseInt(hex.slice(2, 4), 16) / 255, parseInt(hex.slice(4, 6), 16) / 255],
  };
}
