import type { FC } from 'react';
import { useEffect, useState } from 'react';
import { toast } from 'sonner';
import ToolLayout from '@/components/tools/ToolLayout';
import PillGroup from '@/components/tools/PillGroup';
import UploadBox from '@/components/tools/word-to-pdf/UploadBox';
import ConversionResult from '@/components/tools/word-to-pdf/ConversionResult';
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from '@/components/ui/accordion';
import { usePersistentState } from '@/hooks/usePersistentState';
import { convertDocxToPdf } from '@/lib/docx/convert';
import { isLocalFontAccessSupported, requestLocalFontsAccess } from '@/lib/docx/localFonts';
import type { MarginsOption, PageSizeOption } from '@/lib/docx/types';

const PAGE_SIZE_OPTIONS: { value: PageSizeOption; label: string }[] = [
  { value: 'match', label: 'Match document' },
  { value: 'A4', label: 'A4' },
  { value: 'Letter', label: 'Letter' },
  { value: 'Legal', label: 'Legal' },
];

const MARGIN_OPTIONS: { value: MarginsOption; label: string }[] = [
  { value: 'match', label: 'Match document' },
  { value: 'normal', label: 'Normal' },
  { value: 'narrow', label: 'Narrow' },
  { value: 'wide', label: 'Wide' },
];

const CAVEATS = [
  'Only the default header/footer is used — different first-page or even-page headers/footers are simplified to one.',
  'Dynamic fields inside a header/footer (page numbers, dates) are skipped, since only their last-saved value is stored in the file — use the "Page numbers" option above for accurate pagination instead.',
  'Footnotes, endnotes, and multi-column layouts are not reproduced.',
  'Tables render with equal-width columns; merged or spanned cells are simplified to plain cells.',
  'Fonts are matched using open-license, metric-compatible substitutes (e.g. Carlito in place of Calibri, Caladea in place of Cambria) rather than the exact Word font files, since those can’t be redistributed — sizing and spacing match closely, but the letterforms themselves differ slightly. On Chrome or Edge, turning on "Use my installed fonts" below embeds your machine’s actual copies instead, wherever it finds a match.',
  'Only Latin-alphabet text is supported by the built-in fonts — Devanagari, Arabic, CJK, Cyrillic, and Greek characters render as "?" placeholders.',
  'Manual page breaks in the source document are not preserved — pages break automatically as content fills each page.',
  'Legacy vector images (WMF/EMF, common from older Word documents) usually can’t be decoded by the browser and are skipped.',
  'Images are placed at their original resolution rather than a size explicitly set in Word — a deliberately resized image may come out a different size than in the source document.',
];

const WordToPdf: FC = () => {
  const [file, setFile] = usePersistentState<File | null>('word-to-pdf:file', null);
  const [pageSize, setPageSize] = usePersistentState<PageSizeOption>('word-to-pdf:pageSize', 'match');
  const [margins, setMargins] = usePersistentState<MarginsOption>('word-to-pdf:margins', 'match');
  const [includeImages, setIncludeImages] = usePersistentState<boolean>('word-to-pdf:includeImages', true);
  const [includePageNumbers, setIncludePageNumbers] = usePersistentState<boolean>('word-to-pdf:includePageNumbers', true);
  const [includeHeadersFooters, setIncludeHeadersFooters] = usePersistentState<boolean>('word-to-pdf:includeHeadersFooters', true);
  // Not persisted -- a granted permission from a previous visit doesn't
  // guarantee the browser still honors it silently, so each session starts
  // opted out and re-confirms access explicitly when the visitor asks for it.
  const [useLocalFonts, setUseLocalFonts] = useState(false);
  const [requestingLocalFonts, setRequestingLocalFonts] = useState(false);
  const localFontsSupported = isLocalFontAccessSupported();

  const [blob, setBlob] = useState<Blob | null>(null);
  const [pageCount, setPageCount] = useState(0);
  const [warnings, setWarnings] = useState<string[]>([]);
  const [isConverting, setIsConverting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // A converted PDF only reflects the file/options at the moment it was
  // built — once any of that changes, drop the stale result rather than
  // offer an out-of-date download.
  useEffect(() => {
    setBlob(null);
    setError(null);
  }, [file, pageSize, margins, includeImages, includePageNumbers, includeHeadersFooters, useLocalFonts]);

  const handleToggleLocalFonts = async (checked: boolean) => {
    if (!checked) {
      setUseLocalFonts(false);
      return;
    }
    setRequestingLocalFonts(true);
    const granted = await requestLocalFontsAccess();
    setRequestingLocalFonts(false);
    if (granted) {
      setUseLocalFonts(true);
    } else {
      toast.error("Couldn't access your installed fonts — the browser may have blocked or denied the permission request.");
    }
  };

  const handleConvert = () => {
    if (!file) return;
    setError(null);
    setIsConverting(true);

    convertDocxToPdf(file, {
      pageSize,
      margins,
      includeImages,
      includePageNumbers,
      includeHeadersFooters,
      useLocalFonts,
    })
      .then((result) => {
        setBlob(result.blob);
        setPageCount(result.pageCount);
        setWarnings(result.warnings);
        setIsConverting(false);
      })
      .catch((err: Error) => {
        setError(err.message || "This document couldn't be converted");
        setIsConverting(false);
      });
  };

  const fileName = file ? `${file.name.replace(/\.docx$/i, '') || 'document'}.pdf` : 'document.pdf';

  return (
    <ToolLayout
      title="Word to PDF"
      description="Convert a .docx file to PDF entirely in your browser — the text stays real, selectable, and searchable, not a flattened image."
    >
      <div className="max-w-2xl space-y-6">
        <UploadBox file={file} onSelect={setFile} onClear={() => setFile(null)} />

        {file && (
          <>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-5">
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">Page size</h2>
                <PillGroup aria-label="Page size" options={PAGE_SIZE_OPTIONS} value={pageSize} onChange={setPageSize} />
              </div>
              <div>
                <h2 className="text-sm font-medium text-muted-foreground mb-3">Margins</h2>
                <PillGroup aria-label="Margins" options={MARGIN_OPTIONS} value={margins} onChange={setMargins} />
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-5">
              <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={includeImages}
                  onChange={(e) => setIncludeImages(e.target.checked)}
                  className="w-4 h-4 rounded border-input accent-accent"
                />
                Include images
              </label>
              <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={includePageNumbers}
                  onChange={(e) => setIncludePageNumbers(e.target.checked)}
                  className="w-4 h-4 rounded border-input accent-accent"
                />
                Page numbers in footer
              </label>
              <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
                <input
                  type="checkbox"
                  checked={includeHeadersFooters}
                  onChange={(e) => setIncludeHeadersFooters(e.target.checked)}
                  className="w-4 h-4 rounded border-input accent-accent"
                />
                Keep original header/footer
              </label>
              {localFontsSupported && (
                <label className="flex items-center gap-2 text-sm text-foreground/80 cursor-pointer select-none">
                  <input
                    type="checkbox"
                    checked={useLocalFonts}
                    disabled={requestingLocalFonts}
                    onChange={(e) => void handleToggleLocalFonts(e.target.checked)}
                    className="w-4 h-4 rounded border-input accent-accent"
                  />
                  Use my installed fonts (exact Calibri, Times New Roman, etc.)
                </label>
              )}
            </div>

            <ConversionResult
              hasFile={!!file}
              blob={blob}
              pageCount={pageCount}
              warnings={warnings}
              fileName={fileName}
              isConverting={isConverting}
              error={error}
              onGenerate={handleConvert}
            />

            <Accordion type="single" collapsible className="w-full">
              <AccordionItem value="caveats" className="border-t border-b-0">
                <AccordionTrigger className="text-sm text-muted-foreground hover:no-underline">
                  What this does and doesn't reproduce
                </AccordionTrigger>
                <AccordionContent>
                  <p className="text-sm text-muted-foreground leading-relaxed mb-3">
                    Headings, paragraphs, text alignment, bold, italic, underline, strikethrough, superscript/subscript,
                    font family, text color, highlight colors, bullet and numbered lists, tables, images, hyperlinks, and
                    the document's default header/footer all come across, and the resulting text remains selectable and
                    searchable. A few things don't make the trip:
                  </p>
                  <ul className="text-sm text-muted-foreground leading-relaxed list-disc pl-5 space-y-1.5">
                    {CAVEATS.map((caveat) => (
                      <li key={caveat}>{caveat}</li>
                    ))}
                  </ul>
                </AccordionContent>
              </AccordionItem>
            </Accordion>
          </>
        )}
      </div>
    </ToolLayout>
  );
};

export default WordToPdf;
