import type { FC } from 'react';
import { useRef, useState } from 'react';
import { toast } from 'sonner';
import { UploadCloud, X, FileText } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';
import { looksLikeDocx } from '@/lib/docx/convert';

const MAX_BYTES = 30 * 1024 * 1024;

interface UploadBoxProps {
  file: File | null;
  onSelect: (file: File) => void;
  onClear: () => void;
}

const UploadBox: FC<UploadBoxProps> = ({ file, onSelect, onClear }) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [isDragging, setIsDragging] = useState(false);

  const handleFiles = (files: FileList | null) => {
    const picked = files?.[0];
    if (!picked) return;
    if (!looksLikeDocx(picked)) {
      toast.error(picked.name.toLowerCase().endsWith('.doc') ? "Older .doc files aren't supported — only .docx" : 'Please choose a .docx file');
      return;
    }
    if (picked.size > MAX_BYTES) {
      toast.error(`File is too large (max ${formatBytes(MAX_BYTES)})`);
      return;
    }
    onSelect(picked);
  };

  if (file) {
    return (
      <div className="glass-panel hover:border-border px-3.5 py-2.5 flex items-center gap-2.5">
        <FileText className="w-4 h-4 text-muted-foreground shrink-0" />
        <p className="text-sm text-foreground truncate flex-1 min-w-0">
          <span className="font-medium">{file.name}</span> <span className="text-muted-foreground">· {formatBytes(file.size)}</span>
        </p>
        <button
          type="button"
          onClick={onClear}
          aria-label="Remove document"
          className="shrink-0 p-1.5 rounded-full text-muted-foreground hover:text-foreground hover:bg-accent/10 transition-colors"
        >
          <X className="w-3.5 h-3.5" />
        </button>
      </div>
    );
  }

  return (
    <div
      onClick={() => inputRef.current?.click()}
      onDragOver={(e) => {
        e.preventDefault();
        setIsDragging(true);
      }}
      onDragLeave={() => setIsDragging(false)}
      onDrop={(e) => {
        e.preventDefault();
        setIsDragging(false);
        handleFiles(e.dataTransfer.files);
      }}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') inputRef.current?.click();
      }}
      className={`glass-panel flex flex-col items-center justify-center gap-3 py-14 px-6 text-center cursor-pointer transition-colors ${
        isDragging ? 'border-accent/60 bg-accent/5' : 'hover:border-border'
      }`}
    >
      <input
        ref={inputRef}
        type="file"
        accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
        className="hidden"
        onChange={(e) => handleFiles(e.target.files)}
      />
      <UploadCloud className="w-8 h-8 text-muted-foreground/50" />
      <div>
        <p className="text-sm font-medium text-foreground">Drop a .docx file here, or click to browse</p>
        <p className="text-xs text-muted-foreground mt-1">Up to {formatBytes(MAX_BYTES)} · text stays real and selectable, not an image</p>
      </div>
    </div>
  );
};

export default UploadBox;
