import type { FC } from 'react';
import { Download, FileOutput, TriangleAlert } from 'lucide-react';
import { formatBytes } from '@/lib/image/convert';

interface ConversionResultProps {
  hasFile: boolean;
  blob: Blob | null;
  pageCount: number;
  warnings: string[];
  fileName: string;
  isConverting: boolean;
  error: string | null;
  onGenerate: () => void;
}

const ConversionResult: FC<ConversionResultProps> = ({ hasFile, blob, pageCount, warnings, fileName, isConverting, error, onGenerate }) => {
  const handleDownload = () => {
    if (!blob) return;
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = fileName;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  };

  if (error) {
    return (
      <div className="glass-panel p-6 space-y-3">
        <p className="text-sm text-destructive" role="alert">
          {error}
        </p>
        <button
          type="button"
          onClick={onGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <FileOutput className="w-4 h-4" />
          Try again
        </button>
      </div>
    );
  }

  if (isConverting) {
    return (
      <div className="glass-panel p-6 flex items-center gap-3" role="status" aria-live="polite">
        <div className="w-4 h-4 rounded-full border-2 border-accent border-t-transparent animate-spin shrink-0" />
        <p className="text-sm text-muted-foreground">Converting…</p>
      </div>
    );
  }

  if (!hasFile) return null;

  if (!blob) {
    return (
      <div className="glass-panel p-6 flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm text-muted-foreground">Ready when you are.</p>
        <button
          type="button"
          onClick={onGenerate}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <FileOutput className="w-4 h-4" />
          Convert to PDF
        </button>
      </div>
    );
  }

  return (
    <div className="glass-panel hover:border-border p-4 md:p-6 space-y-3">
      <div className="flex items-center justify-between gap-4 flex-wrap">
        <p className="text-sm font-medium text-foreground">
          {pageCount} {pageCount === 1 ? 'page' : 'pages'} · {formatBytes(blob.size)} PDF
        </p>
        <button
          type="button"
          onClick={handleDownload}
          className="inline-flex items-center justify-center gap-2 px-4 py-2.5 rounded-lg text-sm font-medium bg-accent text-accent-foreground hover:bg-accent/90 transition-colors"
        >
          <Download className="w-4 h-4" />
          Download PDF
        </button>
      </div>

      {warnings.length > 0 && (
        <div className="flex items-start gap-2 pt-1 border-t border-border/60">
          <TriangleAlert className="w-3.5 h-3.5 text-amber-500 shrink-0 mt-2.5" />
          <ul className="text-xs text-muted-foreground leading-relaxed pt-2.5 space-y-1">
            {warnings.map((warning, i) => (
              <li key={i}>{warning}</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
};

export default ConversionResult;
