import type { PDFDocument, PDFFont } from 'pdf-lib';
import { detectFontFamily, embedFontResilient, loadFontFamilyBytes, type FontFamilyKey } from './fonts';
import { loadLocalFontVariantBytes } from './localFonts';
import { normalizeText } from './textNormalize';
import type { DocxBlock, DocxRun, LayoutResult, MarginsOption, PageGeometry, ParagraphAlign, PositionedItem, WordToPdfOptions } from './types';
import { normalizeImage } from './image';

// Word's own default when a run has no explicit size of its own (relied on
// for headings too, scaled by HEADING_SCALE, when a heading has no direct
// per-run size override either).
const DEFAULT_BODY_SIZE = 11;
const MARGIN_PRESETS: Record<Exclude<MarginsOption, 'match'>, number> = { normal: 72, narrow: 36, wide: 108 };
const HEADING_SCALE: Record<1 | 2 | 3 | 4 | 5 | 6, number> = { 1: 2, 2: 1.6, 3: 1.35, 4: 1.15, 5: 1.05, 6: 1 };
const LIST_INDENT = 18;
// All three must be encodable by every embedded font — e.g. U+25E6 "white
// bullet" and U+25AA "black small square" aren't in Carlito's glyph set.
const LIST_BULLETS = ['•', 'o', '-'];
const LINE_HEIGHT_FACTOR = 1.25;
const PARAGRAPH_SPACING = 6;
const HEADING_SPACING_BEFORE = 12;
const HEADING_SPACING_AFTER = 6;
const TABLE_CELL_PADDING = 4;
const TABLE_MIN_ROW_HEIGHT = DEFAULT_BODY_SIZE * LINE_HEIGHT_FACTOR;
// Superscript/subscript shrink the glyph and nudge it off the baseline —
// the offset is a fraction of the *surrounding* text's size (standard
// typographic convention), computed once at tokenize time as an absolute
// point value so drawing never has to re-derive the "un-shrunk" size.
const SUPERSCRIPT_SIZE_SCALE = 0.7;
const SUPERSCRIPT_Y_OFFSET_FACTOR = 0.35;
const SUBSCRIPT_Y_OFFSET_FACTOR = -0.12;
// Mirrors render.ts's TEXT_COLOR/LINK_COLOR — kept local so layout can
// decide up front what color an underline/link line should be.
const TEXT_RGB: [number, number, number] = [0.08, 0.08, 0.08];
const LINK_RGB: [number, number, number] = [0.15, 0.35, 0.85];

/** Resolves the requested page-size/margins options against the document's
 * own geometry (only used when either option is "match", and only if it was
 * actually readable — see pageSetup.ts). */
export async function resolvePageGeometry(options: WordToPdfOptions, docGeometry: PageGeometry | null): Promise<PageGeometry> {
  const { PageSizes } = await import('pdf-lib');
  const [a4Width, a4Height] = PageSizes.A4;
  let width = a4Width;
  let height = a4Height;
  if (options.pageSize === 'match' && docGeometry) {
    ({ width, height } = docGeometry);
  } else if (options.pageSize !== 'match') {
    [width, height] = PageSizes[options.pageSize];
  }

  let marginTop = MARGIN_PRESETS.normal;
  let marginRight = MARGIN_PRESETS.normal;
  let marginBottom = MARGIN_PRESETS.normal;
  let marginLeft = MARGIN_PRESETS.normal;
  if (options.margins === 'match' && docGeometry) {
    ({ marginTop, marginRight, marginBottom, marginLeft } = docGeometry);
  } else if (options.margins !== 'match') {
    marginTop = marginRight = marginBottom = marginLeft = MARGIN_PRESETS[options.margins];
  }

  return { width, height, marginTop, marginRight, marginBottom, marginLeft };
}

interface Token {
  text: string;
  size: number; // already includes superscript/subscript shrinking
  yOffset: number; // absolute points to shift the baseline; 0 for normal text
  fontFamily: FontFamilyKey;
  rawFont?: string | null;
  bold: boolean;
  italic: boolean;
  underline?: boolean;
  highlightColor?: [number, number, number];
  color?: [number, number, number];
  href?: string;
  isSpace: boolean;
}

interface PlacedToken {
  token: Token;
  font: PDFFont;
  width: number;
}

// A from-scratch, page-agnostic layout pass: walks the parsed blocks once,
// wrapping rich text (mixed bold/italic/font/size/color) against the
// content width and paginating as it goes. Measures against a throwaway
// PDFDocument (pdf-lib fonts are only valid within the document that
// embedded them) — the actual render pass (render.ts) re-embeds fonts in
// the real output document and just replays these positions, so layout
// only needs to run once.
class LayoutEngine {
  private pages: PositionedItem[][] = [[]];
  private cursorY: number;
  private readonly contentWidth: number;
  private readonly contentTop: number;
  private readonly contentBottom: number;
  private readonly marginLeft: number;
  private fontCache = new Map<string, PDFFont>();
  private characterSets = new Map<PDFFont, Set<number>>();
  private orderedCounters: number[] = [];
  private unsupportedCharCount = 0;
  private skippedImageCount = 0;

  private constructor(
    private measureDoc: PDFDocument,
    private geometry: PageGeometry,
    private options: WordToPdfOptions,
  ) {
    this.contentWidth = geometry.width - geometry.marginLeft - geometry.marginRight;
    this.contentTop = geometry.height - geometry.marginTop;
    this.contentBottom = geometry.marginBottom;
    this.marginLeft = geometry.marginLeft;
    this.cursorY = this.contentTop;
  }

  static async run(blocks: DocxBlock[], geometry: PageGeometry, options: WordToPdfOptions): Promise<LayoutResult> {
    const [{ PDFDocument }, { default: fontkit }] = await Promise.all([import('pdf-lib'), import('@pdf-lib/fontkit')]);
    const measureDoc = await PDFDocument.create();
    measureDoc.registerFontkit(fontkit);
    const engine = new LayoutEngine(measureDoc, geometry, options);
    await engine.layoutAll(blocks);
    return engine.finish();
  }

  private async getFont(rawFont: string | null | undefined, family: FontFamilyKey, bold: boolean, italic: boolean): Promise<PDFFont> {
    const key = this.options.useLocalFonts ? `local:${(rawFont ?? '').toLowerCase()}|${bold}|${italic}` : `${family}|${bold}|${italic}`;
    let font = this.fontCache.get(key);
    if (!font) {
      if (this.options.useLocalFonts) {
        const localBytes = await loadLocalFontVariantBytes(rawFont, bold, italic);
        if (localBytes) font = (await embedFontResilient(this.measureDoc, localBytes)) ?? undefined;
      }
      if (!font) {
        const variants = await loadFontFamilyBytes(family);
        const bytes = bold && italic ? variants.boldItalic : bold ? variants.bold : italic ? variants.italic : variants.regular;
        font = await this.measureDoc.embedFont(bytes, { subset: true });
      }
      this.fontCache.set(key, font);
    }
    return font;
  }

  private characterSetOf(font: PDFFont): Set<number> {
    let set = this.characterSets.get(font);
    if (!set) {
      set = new Set(font.getCharacterSet());
      this.characterSets.set(font, set);
    }
    return set;
  }

  private sanitize(text: string, font: PDFFont): string {
    const normalized = normalizeText(text);
    const charSet = this.characterSetOf(font);
    let out = '';
    for (const ch of normalized) {
      const supported = charSet.has(ch.codePointAt(0) ?? 0);
      if (!supported) this.unsupportedCharCount++;
      out += supported ? ch : '?';
    }
    return out;
  }

  private currentPage(): PositionedItem[] {
    return this.pages[this.pages.length - 1];
  }

  private newPage(): void {
    this.pages.push([]);
    this.cursorY = this.contentTop;
  }

  private ensureSpace(height: number): void {
    if (this.cursorY - height < this.contentBottom) this.newPage();
  }

  private async tokenize(runs: DocxRun[], fallbackSize: number): Promise<{ token: Token; font: PDFFont }[]> {
    const out: { token: Token; font: PDFFont }[] = [];
    for (const run of runs) {
      const family = detectFontFamily(run.font);
      const font = await this.getFont(run.font, family, run.bold, run.italic);
      const baseSize = run.fontSize ?? fallbackSize;
      const isSupSub = !!(run.superscript || run.subscript);
      const size = isSupSub ? baseSize * SUPERSCRIPT_SIZE_SCALE : baseSize;
      const yOffset = run.superscript ? baseSize * SUPERSCRIPT_Y_OFFSET_FACTOR : run.subscript ? baseSize * SUBSCRIPT_Y_OFFSET_FACTOR : 0;

      const shared = {
        size,
        yOffset,
        fontFamily: family,
        rawFont: run.font,
        bold: run.bold,
        italic: run.italic,
        underline: run.underline,
        highlightColor: run.highlightColor,
        color: run.color ?? undefined,
        href: run.href,
      };

      // A <br>/line-break comes through as a literal "\n" in the run's text.
      run.text.split('\n').forEach((segment, i) => {
        if (i > 0) out.push({ token: { text: '\n', ...shared, isSpace: false }, font });
        segment
          .split(/(\s+)/)
          .filter((part) => part !== '')
          .forEach((part) => {
            out.push({ token: { text: this.sanitize(part, font), ...shared, isSpace: /^\s+$/.test(part) }, font });
          });
      });
    }
    return out;
  }

  private wrap(tokens: { token: Token; font: PDFFont }[], availWidth: number): PlacedToken[][] {
    const lines: PlacedToken[][] = [];
    let line: PlacedToken[] = [];
    let width = 0;

    for (const { token, font } of tokens) {
      if (token.text === '\n') {
        lines.push(line);
        line = [];
        width = 0;
        continue;
      }
      const w = font.widthOfTextAtSize(token.text, token.size);
      if (token.isSpace) {
        if (line.length > 0) {
          line.push({ token, font, width: w });
          width += w;
        }
        continue;
      }
      if (width + w > availWidth && line.length > 0) {
        lines.push(line);
        line = [];
        width = 0;
      }
      line.push({ token, font, width: w });
      width += w;
    }
    if (line.length > 0) lines.push(line);
    return lines;
  }

  private drawLine(line: PlacedToken[], startX: number, extraSpacePerGap: number): void {
    const lineSize = Math.max(1, ...line.map((t) => t.token.size));
    const lineHeight = lineSize * LINE_HEIGHT_FACTOR;
    this.ensureSpace(lineHeight);
    const baselineY = this.cursorY - lineSize * 0.82;
    let x = startX;

    for (const { token, width } of line) {
      const y = baselineY + token.yOffset;
      if (token.text.trim() !== '') {
        if (token.highlightColor) {
          this.currentPage().push({ type: 'rect', x, y: baselineY - lineSize * 0.22, width, height: lineSize * 1.1, fill: token.highlightColor });
        }
        this.currentPage().push({
          type: 'text',
          x,
          y,
          text: token.text,
          size: token.size,
          fontFamily: token.fontFamily,
          rawFont: token.rawFont,
          bold: token.bold,
          italic: token.italic,
          underline: token.underline,
          color: token.color,
          href: token.href,
        });
        if (token.href || token.underline) {
          this.currentPage().push({ type: 'line', x1: x, y1: y - 1, x2: x + width, y2: y - 1, color: token.href ? LINK_RGB : (token.color ?? TEXT_RGB) });
        }
      }
      x += token.isSpace ? width + extraSpacePerGap : width;
    }
    this.cursorY -= lineHeight;
  }

  private async layoutRuns(
    runs: DocxRun[],
    opts: { fallbackSize: number; indentX?: number; prefix?: string; spacingAfter?: number; align?: ParagraphAlign },
  ): Promise<void> {
    const indentX = opts.indentX ?? 0;
    const availWidth = this.contentWidth - indentX;
    const align = opts.align ?? 'left';

    const tokens = await this.tokenize(runs, opts.fallbackSize);
    if (opts.prefix) {
      const font = await this.getFont(null, 'carlito', false, false);
      const prefixShared = { size: opts.fallbackSize, yOffset: 0, fontFamily: 'carlito' as FontFamilyKey, bold: false, italic: false };
      tokens.unshift(
        { token: { text: this.sanitize(opts.prefix, font), ...prefixShared, isSpace: false }, font },
        { token: { text: ' ', ...prefixShared, isSpace: true }, font },
      );
    }

    const lines = this.wrap(tokens, availWidth);
    if (lines.length === 0) return;

    const baseX = this.marginLeft + indentX;
    lines.forEach((line, i) => {
      const naturalWidth = line.reduce((sum, t) => sum + t.width, 0);
      const isLastLine = i === lines.length - 1;
      let startX = baseX;
      let extraSpacePerGap = 0;

      if (align === 'center') {
        startX = baseX + Math.max(0, (availWidth - naturalWidth) / 2);
      } else if (align === 'right') {
        startX = baseX + Math.max(0, availWidth - naturalWidth);
      } else if (align === 'justify' && !isLastLine) {
        const spaceCount = line.filter((t) => t.token.isSpace).length;
        const extra = availWidth - naturalWidth;
        if (spaceCount > 0 && extra > 0) extraSpacePerGap = extra / spaceCount;
      }

      this.drawLine(line, startX, extraSpacePerGap);
    });
    if (opts.spacingAfter) this.cursorY -= opts.spacingAfter;
  }

  private async layoutTable(rows: DocxRun[][][]): Promise<void> {
    const numCols = Math.max(...rows.map((r) => r.length));
    if (numCols === 0) return;
    const colWidth = this.contentWidth / numCols;

    for (const row of rows) {
      // Every cell is wrapped before anything is drawn, so the row's full
      // height is known up front — a row never starts on one page and
      // finishes on the next.
      const cellLines = await Promise.all(
        Array.from({ length: numCols }, async (_, i) => {
          const tokens = await this.tokenize(row[i] ?? [], DEFAULT_BODY_SIZE);
          return this.wrap(tokens, colWidth - TABLE_CELL_PADDING * 2);
        }),
      );
      const cellHeights = cellLines.map((lines) =>
        lines.reduce((sum, line) => sum + Math.max(1, ...line.map((t) => t.token.size)) * LINE_HEIGHT_FACTOR, 0),
      );
      const rowHeight = Math.max(TABLE_MIN_ROW_HEIGHT, ...cellHeights) + TABLE_CELL_PADDING * 2;

      this.ensureSpace(rowHeight);
      const rowTop = this.cursorY;

      cellLines.forEach((lines, colIndex) => {
        const cellX = this.marginLeft + colIndex * colWidth;
        this.currentPage().push({ type: 'rect', x: cellX, y: rowTop - rowHeight, width: colWidth, height: rowHeight });

        let lineY = rowTop - TABLE_CELL_PADDING;
        lines.forEach((line) => {
          const lineSize = Math.max(1, ...line.map((t) => t.token.size));
          const baselineY = lineY - lineSize * 0.82;
          let x = cellX + TABLE_CELL_PADDING;
          line.forEach(({ token, width }) => {
            const y = baselineY + token.yOffset;
            if (token.text.trim() !== '') {
              if (token.highlightColor) {
                this.currentPage().push({ type: 'rect', x, y: baselineY - lineSize * 0.22, width, height: lineSize * 1.1, fill: token.highlightColor });
              }
              this.currentPage().push({
                type: 'text',
                x,
                y,
                text: token.text,
                size: token.size,
                fontFamily: token.fontFamily,
                rawFont: token.rawFont,
                bold: token.bold,
                italic: token.italic,
                underline: token.underline,
                color: token.color,
              });
              if (token.underline) {
                this.currentPage().push({ type: 'line', x1: x, y1: y - 1, x2: x + width, y2: y - 1, color: token.color ?? TEXT_RGB });
              }
            }
            x += width;
          });
          lineY -= lineSize * LINE_HEIGHT_FACTOR;
        });
      });

      this.cursorY = rowTop - rowHeight;
    }
    this.cursorY -= PARAGRAPH_SPACING;
  }

  private async layoutImage(dataUrl: string): Promise<void> {
    if (!this.options.includeImages) return;
    const normalized = await normalizeImage(dataUrl);
    if (!normalized) {
      this.skippedImageCount++;
      return;
    }

    const maxWidth = this.contentWidth;
    const maxHeight = (this.contentTop - this.contentBottom) * 0.9;
    const fitScale = Math.min(maxWidth / normalized.width, maxHeight / normalized.height);
    // Mammoth only gives us the image's native pixel size, not the display
    // size the source document may have explicitly scaled it to — a small
    // icon-sized image would otherwise render as a near-invisible dot. If it
    // already needs shrinking to fit, always shrink; otherwise grow it
    // toward a sensible minimum width, capped so a tiny source image doesn't
    // get blown up into a blurry mess.
    const MIN_DISPLAY_WIDTH = Math.min(200, maxWidth);
    const MAX_UPSCALE = 4;
    const scale =
      fitScale < 1 ? fitScale : Math.min(fitScale, Math.max(1, Math.min(MIN_DISPLAY_WIDTH / normalized.width, MAX_UPSCALE)));
    const width = normalized.width * scale;
    const height = normalized.height * scale;

    this.ensureSpace(height);
    this.cursorY -= height;
    this.currentPage().push({ type: 'image', x: this.marginLeft, y: this.cursorY, width, height, dataUrl: normalized.dataUrl, format: normalized.format });
    this.cursorY -= PARAGRAPH_SPACING;
  }

  private async layoutListItem(ordered: boolean, level: number, runs: DocxRun[], align?: ParagraphAlign): Promise<void> {
    this.orderedCounters.length = level + 1;
    let prefix: string;
    if (ordered) {
      this.orderedCounters[level] = (this.orderedCounters[level] ?? 0) + 1;
      prefix = `${this.orderedCounters[level]}.`;
    } else {
      this.orderedCounters[level] = 0;
      prefix = LIST_BULLETS[level % LIST_BULLETS.length];
    }
    await this.layoutRuns(runs, { fallbackSize: DEFAULT_BODY_SIZE, indentX: LIST_INDENT * (level + 1), prefix, spacingAfter: PARAGRAPH_SPACING, align });
  }

  private async layoutAll(blocks: DocxBlock[]): Promise<void> {
    let lastWasList = false;
    for (const block of blocks) {
      if (block.kind !== 'list-item' && lastWasList) this.orderedCounters = [];
      lastWasList = block.kind === 'list-item';

      if (block.kind === 'heading') {
        this.cursorY -= HEADING_SPACING_BEFORE;
        // Real heading sizes/boldness come from the document's own
        // "HeadingN" style (resolved in parse.ts) whenever it defines
        // them -- HEADING_SCALE is only a fallback for the rare document
        // whose heading style doesn't specify a size at all.
        await this.layoutRuns(block.runs, {
          fallbackSize: DEFAULT_BODY_SIZE * HEADING_SCALE[block.level],
          spacingAfter: HEADING_SPACING_AFTER,
          align: block.align,
        });
      } else if (block.kind === 'paragraph') {
        await this.layoutRuns(block.runs, { fallbackSize: DEFAULT_BODY_SIZE, spacingAfter: PARAGRAPH_SPACING, align: block.align });
      } else if (block.kind === 'list-item') {
        await this.layoutListItem(block.ordered, block.level, block.runs, block.align);
      } else if (block.kind === 'table') {
        await this.layoutTable(block.rows);
      } else if (block.kind === 'image') {
        await this.layoutImage(block.dataUrl);
      }
    }
  }

  private finish(): LayoutResult {
    const warnings: string[] = [];
    if (this.unsupportedCharCount > 0) {
      warnings.push(
        `${this.unsupportedCharCount} character${this.unsupportedCharCount === 1 ? '' : 's'} couldn't be rendered by the available fonts and ${this.unsupportedCharCount === 1 ? 'was' : 'were'} replaced with "?".`,
      );
    }
    if (this.skippedImageCount > 0) {
      warnings.push(
        `${this.skippedImageCount} image${this.skippedImageCount === 1 ? '' : 's'} in an unsupported format couldn't be converted and ${this.skippedImageCount === 1 ? 'was' : 'were'} skipped.`,
      );
    }
    return { pages: this.pages, warnings };
  }
}

export async function layoutDocument(blocks: DocxBlock[], geometry: PageGeometry, options: WordToPdfOptions): Promise<LayoutResult> {
  return LayoutEngine.run(blocks, geometry, options);
}
